arguments.new_str:
using System;
using System.Numerics;
using System.Runtime.InteropServices;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        int i = 0;

        if (Vector.IsHardwareAccelerated && data.Length >= Vector<int>.Count)
        {
            var vThreshold = new Vector<int>(threshold);
            var vSpan = MemoryMarshal.Cast<int, Vector<int>>(data);

            for (int vi = 0; vi < vSpan.Length; vi++)
            {
                // GreaterThan returns -1 for matching lanes; subtracting -1 adds 1.
                vSpan[vi] -= Vector.GreaterThan(vSpan[vi], vThreshold);
            }

            i = vSpan.Length * Vector<int>.Count;
        }

        for (; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }
}

